import Testing

@testable import TopdeckFeatures

struct ClipboardRulesTests {
    private let rules = ClipboardRules(ignoredApps: ["com.apple.Terminal"])

    @Test(arguments: [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
    ])
    func markedCopiesAreSkippedFromAnyApp(type: String) {
        #expect(rules.ignores(types: ["public.utf8-plain-text", type], apps: ["com.apple.TextEdit"]))
        #expect(rules.ignores(types: [type], apps: [nil, nil]), "even when the app isn't known")
    }

    @Test func passwordManagerTypesAreSkipped() {
        let onePassword = ["public.utf8-plain-text", "com.agilebits.onepassword"]
        #expect(rules.ignores(types: onePassword, apps: ["com.apple.Safari"]))
        #expect(rules.ignores(types: ["net.antelle.keeweb"], apps: []))
    }

    @Test func passwordManagersAreSkippedWithoutBeingListed() {
        let none = ClipboardRules()
        for app in ClipboardRules.passwordManagers {
            #expect(none.ignores(types: ["public.utf8-plain-text"], apps: [app]), "\(app)")
        }
        #expect(none.ignores(types: ["public.utf8-plain-text"], apps: ["COM.BITWARDEN.DESKTOP"]), "any case")
    }

    @Test func aCopyNamingAPasswordManagerAsItsSourceIsSkipped() {
        // 1Password's browser extension copies while the browser is in front.
        #expect(rules.ignores(types: ["public.utf8-plain-text"], apps: ["com.apple.Safari", "com.1password.1password"]))
    }

    @Test func listedAppsAreSkippedAndOthersKept() {
        let text = ["public.utf8-plain-text"]
        #expect(rules.ignores(types: text, apps: ["com.apple.Terminal", nil]))
        #expect(rules.ignores(types: text, apps: ["com.apple.terminal"]))
        #expect(!rules.ignores(types: text, apps: ["com.apple.TextEdit", nil]))
        #expect(!rules.ignores(types: text, apps: [nil, nil]))
        #expect(!ClipboardRules().ignores(types: text, apps: ["com.apple.Terminal"]), "only while listed")
    }
}

struct LinkCleanerTests {
    @Test(arguments: [
        ("https://example.com/a?utm_source=news&utm_medium=mail", "https://example.com/a"),
        ("https://example.com/a?id=7&utm_campaign=x&ref=home", "https://example.com/a?id=7&ref=home"),
        ("https://shop.example/p?fbclid=abc&gclid=def&q=red%20shoes", "https://shop.example/p?q=red%20shoes"),
        ("https://example.com/?UTM_Source=x#section-2", "https://example.com/#section-2"),
        ("http://example.com/a?utm%5Fsource=x&b=1", "http://example.com/a?b=1"),
        ("https://example.com/a?msclkid=1&mc_cid=2&mc_eid=3&_hsenc=4", "https://example.com/a"),
        ("  https://example.com/a?utm_source=x\n", "  https://example.com/a\n"),
    ])
    func trackingParametersAreRemoved(link: String, cleaned: String) {
        #expect(LinkCleaner.clean(link) == cleaned)
    }

    @Test(arguments: [
        "https://example.com/a?id=7&ref=home",  // nothing to remove
        "https://example.com/a?b=1&&c=%2F",  // left exactly as copied
        "https://example.com/search?utm=1&utm_=2",  // not a campaign tag
        "https://exa mple.com/?utm_source=x",  // doesn't parse
        "https://example.com/a b?utm_source=x",
        "https://example.com/?q=a b&utm_source=x",
        "https://example.com/a?q=%zz&utm_source=x",
        "https://example.com/#top?utm_source=x",  // in the fragment, not the query
        "ftp://example.com/file?utm_source=x",  // not a web link
        "mailto:someone@example.com?utm_source=x",
        "/relative/path?utm_source=x",
        "see https://example.com/?utm_source=x for details",  // text around a link
        "utm_source=x",
        "",
    ])
    func otherTextIsLeftAlone(text: String) {
        #expect(LinkCleaner.clean(text) == text)
    }
}
